=== FILE: uart_tx_reload_repro_tb.v ===
// Repro for uart_tx: per the module contract, "A start pulse while a frame is
// in flight is ignored." This testbench sends 0xA5, pulses start with 0x3C while
// the frame is in flight, and checks that 0xA5 is what appears on tx (8N1, LSB
// first, CLKS_PER_BIT clocks per bit). Expected values come from the contract.
`timescale 1ns / 1ps
module uart_tx_reload_repro_tb;
    localparam integer CLKS_PER_BIT = 4;
    localparam integer HALF         = CLKS_PER_BIT / 2;
    localparam integer NCHARS       = 256;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire       tx;
    wire       busy;

    uart_tx #(.CLKS_PER_BIT(CLKS_PER_BIT)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    reg [8*NCHARS-1:0] nonce;
    reg [8*NCHARS-1:0] raw;
    reg                found;
    integer            n_pass = 0;
    integer            n_fail = 0;
    reg                done   = 1'b0;

    reg       rx_start_ok;
    reg       rx_stop_ok;
    reg [7:0] rx_byte;
    integer   i;
    integer   k;
    integer   p;
    integer   q;
    integer   eqpos;
    reg [7:0] ch;

    task check(input cond, input [8*56-1:0] what);
        begin
            if (cond)
                n_pass = n_pass + 1;
            else begin
                n_fail = n_fail + 1;
                $display("CHECK FAILED: %0s", what);
            end
        end
    endtask

    // Strip a leading "<name>=" from raw (characters are right-aligned, so the
    // first '=' in the string is the '=' at the highest byte index).
    task strip_name;
        begin
            eqpos = -1;
            for (p = NCHARS - 1; p >= 0; p = p - 1)
                if ((eqpos < 0) && (raw[p*8 +: 8] == 8'h3D))
                    eqpos = p;
            if (eqpos >= 0)
                for (q = eqpos; q < NCHARS; q = q + 1)
                    raw[q*8 +: 8] = 8'h00;
            nonce = raw;
            found = 1'b1;
        end
    endtask

    task read_nonce;
        begin
            nonce = 0;
            raw   = 0;
            found = 1'b0;
            if ($value$plusargs("NIRMAAN_NONCE=%s", raw)) begin
                nonce = raw; found = 1'b1;
            end else if ($value$plusargs("nirmaan_nonce=%s", raw)) begin
                nonce = raw; found = 1'b1;
            end else if ($value$plusargs("NONCE=%s", raw)) begin
                nonce = raw; found = 1'b1;
            end else if ($value$plusargs("nonce=%s", raw)) begin
                nonce = raw; found = 1'b1;
            end else if ($value$plusargs("NIRMAAN%s", raw)) begin
                strip_name;
            end else if ($value$plusargs("nirmaan%s", raw)) begin
                strip_name;
            end else if ($value$plusargs("Nirmaan%s", raw)) begin
                strip_name;
            end else if ($value$plusargs("NONCE%s", raw)) begin
                strip_name;
            end else if ($value$plusargs("nonce%s", raw)) begin
                strip_name;
            end
`ifdef NIRMAAN_NONCE
            if (!found) begin
                nonce = `NIRMAAN_NONCE;
                found = 1'b1;
            end
`endif
        end
    endtask

    task print_verdict;
        begin
            $write("NIRMAAN-SIM ");
            for (k = NCHARS - 1; k >= 0; k = k - 1) begin
                ch = nonce[k*8 +: 8];
                if (ch != 8'h00)
                    $write("%c", ch);
            end
            $display(" %0d passed, %0d failed", n_pass, n_fail);
        end
    endtask

    // UART-style receiver: falling edge of tx, then sample mid-bit.
    task receive_frame;
        begin
            @(negedge tx);
            repeat (HALF) @(posedge clk);
            #1 rx_start_ok = (tx === 1'b0);
            for (i = 0; i < 8; i = i + 1) begin
                repeat (CLKS_PER_BIT) @(posedge clk);
                #1 rx_byte[i] = tx;
            end
            repeat (CLKS_PER_BIT) @(posedge clk);
            #1 rx_stop_ok = (tx === 1'b1);
        end
    endtask

    task pulse_start(input [7:0] d);
        begin
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
            data  = 8'h00;
        end
    endtask

    initial begin
        read_nonce;

        // Reset
        repeat (4) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (2) @(negedge clk);
        check((tx === 1'b1) && (busy === 1'b0), "idle after reset: tx high, busy low");

        // Frame 1: 0xA5, with a start pulse (0x3C) while the frame is in flight
        fork
            receive_frame;
            begin
                pulse_start(8'hA5);
                @(negedge clk);
                check(busy === 1'b1, "frame in flight before second start pulse");
                pulse_start(8'h3C);
            end
        join
        check(rx_start_ok === 1'b1, "frame 1 start bit low");
        if (rx_byte !== 8'hA5)
            $display("frame 1 byte: expected 0xA5, received 0x%h", rx_byte);
        check(rx_byte === 8'hA5, "frame 1 byte unchanged by start while busy");
        check(rx_stop_ok === 1'b1, "frame 1 stop bit high");

        // The ignored pulse must not launch another frame
        repeat (2 * CLKS_PER_BIT) @(posedge clk);
        #1 check((busy === 1'b0) && (tx === 1'b1), "idle after frame 1: no extra frame");

        // Sanity frame with no interference: 0x5A
        fork
            receive_frame;
            pulse_start(8'h5A);
        join
        check(rx_byte === 8'h5A, "frame 2 byte (no interference)");
        check(rx_stop_ok === 1'b1, "frame 2 stop bit high");

        repeat (2 * CLKS_PER_BIT) @(posedge clk);
        if (!done) begin
            done = 1'b1;
            print_verdict;
        end
        $finish;
    end

    // Watchdog: a frame that never arrives is a failed check, reported once.
    initial begin
        #100000;
        if (!done) begin
            done   = 1'b1;
            n_fail = n_fail + 1;
            $display("CHECK FAILED: watchdog timeout");
            print_verdict;
            $finish;
        end
    end
endmodule
=== END FILE ===
